<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import type { AgentMemoryItem } from '../types'
import { answerStrategyCategory, answerStrategyCategoryLabels } from '../answerStrategyCategories'
import AnswerStrategyIcon from './AnswerStrategyIcon.vue'

const props = defineProps<{ items: AgentMemoryItem[]; scopeKey: string; editingId: number | null; mutatingId: number | null; deleteConfirmId: number | null; loading?: boolean; error?: string }>()
const emit = defineEmits<{ edit: [item: AgentMemoryItem]; delete: [item: AgentMemoryItem]; refresh: [] }>()
const query = ref(''), copiedId = ref<number | null>(null), copyErrorId = ref<number | null>(null)
const entries = computed(() => props.items.map((item, index) => ({ item, index, category: answerStrategyCategory(item) })))
const filtered = computed(() => {
  const search = query.value.trim().toLowerCase()
  return search ? entries.value.filter(({ item, category }) => [item.target, item.memory_key, item.current_version?.content_text, answerStrategyCategoryLabels[category]].join(' ').toLowerCase().includes(search)) : entries.value
})
watch(() => props.scopeKey, () => { query.value = ''; copiedId.value = null; copyErrorId.value = null })
async function copyContent(item: AgentMemoryItem) {
  const scope = props.scopeKey
  copyErrorId.value = null
  try {
    await navigator.clipboard.writeText([item.target || item.memory_key, item.current_version?.content_text || ''].join('\n'))
    if (scope === props.scopeKey) copiedId.value = item.id
  } catch { if (scope === props.scopeKey) copyErrorId.value = item.id }
}
</script>

<template>
  <section class="answer-strategy-panel" aria-label="回答策略管理">
    <header class="answer-strategy-header">
      <div class="answer-strategy-heading"><i aria-hidden="true"><AnswerStrategyIcon category="language" /></i><div><h3>回答策略</h3><p>为常见问题配置专业的回答策略，提升智能体的回复质量与一致性</p></div></div>
      <div class="answer-strategy-toolbar"><label><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="7" /><path d="m15 15 6 6" /></svg><input v-model="query" type="search" aria-label="搜索回答策略" maxlength="200" placeholder="搜索策略名称、关键词…" /></label><button type="button" :disabled="!!mutatingId" @click="emit('refresh')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 7v5h-5M4 17v-5h5M5 8a8 8 0 0 1 13-3l2 2M4 17l2 2a8 8 0 0 0 13-3" /></svg>刷新策略</button></div>
    </header>
    <p v-if="error" class="answer-strategy-copy-error" role="alert">{{ error }}</p>
    <p class="answer-strategy-count" role="status">{{ loading ? '正在读取当前方案回答策略…' : query.trim() ? `找到 ${filtered.length} 条匹配策略` : `共 ${items.length} 条回答策略` }}</p>
    <div v-if="!filtered.length && !loading && !error" class="answer-strategy-empty"><AnswerStrategyIcon category="general" /><strong>{{ items.length ? '没有找到匹配的回答策略' : '当前方案还没有已采用的回答策略' }}</strong><span>{{ items.length ? '换个关键词，或清空搜索看看吧。' : '在当前方案内确认的回答规则会展示在这里。' }}</span></div>
    <div v-else class="answer-strategy-list">
      <article v-for="{ item, index, category } in filtered" :key="item.id" :data-answer-strategy-id="item.id" :data-answer-strategy-category="category" :class="['answer-strategy-card', 'is-' + category, { editing: editingId === item.id }]">
        <aside class="answer-strategy-category"><i><AnswerStrategyIcon :category="category" /></i><strong>{{ answerStrategyCategoryLabels[category] }}</strong></aside>
        <div class="answer-strategy-content"><AnswerStrategyIcon class="answer-strategy-watermark" :category="category" /><h4>{{ item.target || item.memory_key }}</h4><p>{{ item.current_version?.content_text || '当前版本暂无文字内容' }}</p><small class="answer-strategy-version"><span>记忆键</span>{{ item.memory_key }} · V{{ item.current_version?.version_no || 1 }}</small></div>
        <div class="answer-strategy-controls">
          <div class="answer-strategy-status"><span>#{{ String(index + 1).padStart(2, '0') }}</span><strong :class="{ inactive: item.status !== 'active' }"><i aria-hidden="true"></i>{{ item.status === 'active' ? '已启用' : '未启用' }}</strong></div>
          <div class="answer-strategy-actions">
            <button type="button" :disabled="!!mutatingId" @click="emit('edit', item)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 5 5 5M4 20l5-1L21 7a3 3 0 0 0-4-4L5 15zM11 4H3v17h17v-9" /></svg>{{ editingId === item.id ? '收起修改' : '修改' }}</button>
            <button type="button" :aria-label="copiedId === item.id ? '策略内容已复制' : '复制策略内容'" @click="copyContent(item)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 3h13v14h-4M3 7h13v14H3z" /></svg>{{ copiedId === item.id ? '已复制' : '复制内容' }}</button>
            <button type="button" class="is-delete" :class="{ confirming: deleteConfirmId === item.id }" :disabled="!!mutatingId" @click="emit('delete', item)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7" /></svg>{{ mutatingId === item.id ? '处理中…' : deleteConfirmId === item.id ? '确认删除' : '删除' }}</button>
            <details class="answer-strategy-details"><summary aria-label="查看策略详情" title="查看策略详情">•••</summary><div><strong>策略详情</strong><dl><dt>策略名称</dt><dd>{{ item.target || item.memory_key }}</dd><dt>版本</dt><dd>V{{ item.current_version?.version_no || 1 }}</dd><dt>更新时间</dt><dd>{{ new Date(item.updated_at).toLocaleString('zh-CN') }}</dd><dt>当前状态</dt><dd>{{ item.status === 'active' ? '已启用' : '未启用' }}</dd></dl></div></details>
          </div>
          <p v-if="copyErrorId === item.id" class="answer-strategy-copy-error" role="alert">复制没有成功，请重试或手动选择策略文字复制。</p>
        </div>
        <div v-if="editingId === item.id" class="answer-strategy-editor"><slot name="editor" :item="item" /></div>
      </article>
    </div>
  </section>
</template>

