.answer-strategy-controls{display:flex;flex-direction:column;justify-content:center;gap:16px;min-width:0;padding:6px 0 6px 19px;border-left:1px solid #e8edfb}.answer-strategy-status{display:flex;align-items:center;gap:15px}.answer-strategy-status>span{padding-right:15px;border-right:1px solid #e2e9ff;color:#a2b2e8;font-size:16px}.answer-strategy-status strong{display:inline-flex;align-items:center;gap:7px;padding:7px 12px;border-radius:999px;background:#e5f8ef;color:#16a778;font-size:16px;font-weight:800}.answer-strategy-status strong i{width:7px;height:7px;border-radius:50%;background:currentColor}.answer-strategy-status strong.inactive{background:#f0f3fb;color:#8c9abb}
